{
  "cleanupPeriodDays": 20,
  "env": {
    "ANTHROPIC_BASE_URL": "http://127.0.0.1:8011",
    "ANTHROPIC_AUTH_TOKEN": "sk-1234",
    "CLAUDE_CODE_EFFORT_LEVEL": "max",
    "CLAUDE_CODE_ATTRIBUTION_HEADER": "0"
  },
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|compact",
        "hooks": [
          {
            "type": "command",
            "command": "\"/root/.claude/hooks/run-hook.cmd\" session-start-ascendc-ops-lab-developer",
            "async": false
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"/root/.claude/hooks/skill_script_hook.py\"",
            "async": false
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"/root/.claude/hooks/doc_gate.py\" --mode pre",
            "async": false
          }
        ]
      },
      {
        "matcher": "Read",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"/root/.claude/hooks/doc_gate.py\" --mode read_pre",
            "async": false
          }
